// Copies the compiler-generated Rune grammar and language configuration into
// the extension (RN16, ADR 0003). The sources are generated by
// `pherolang grammar --out site/packages/highlighting` and checked by
// `pherolang grammar --check`; never hand-edit the copies, which are
// gitignored.
import { copyFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const pkg = join(here, '..', '..', 'site', 'packages', 'highlighting');

mkdirSync(join(here, 'syntaxes'), { recursive: true });
copyFileSync(
  join(pkg, 'grammars', 'rosetta.tmLanguage.json'),
  join(here, 'syntaxes', 'rosetta.tmLanguage.json'),
);
copyFileSync(
  join(pkg, 'language-configurations', 'rosetta.json'),
  join(here, 'language-configuration.json'),
);
console.log('copied the generated rosetta grammar and language configuration');
